System.register([],function(e,a){"use strict";return{execute:function(){e("c",[{slug:"business-connectors",title:"Business Connectors",subtitle:"Empowering users to unlock loyalty perks across Microsoft Copilot",coverImage:{src:"/assets/business-connectors/Connectors1.jpg",avif:"/assets/business-connectors/Connectors1.avif",webp:"/assets/business-connectors/Connectors1.webp",alt:"Business Connectors hero",aspectRatio:"16/9"},transitionImages:[{src:"/assets/business-connectors/Connector Settings 1.jpg",alt:"Transition 1"},{src:"/assets/business-connectors/Settings Overlay 3.jpg",alt:"Transition 2"},{src:"/assets/business-connectors/PDP + Connector Upsell.jpg",alt:"Transition 3"},{src:"/assets/business-connectors/Connectors.jpg",alt:"Transition 4"},{src:"/assets/business-connectors/Perks.jpg",alt:"Transition 5"}],heroHeadline:"Unlocking Loyalty Rewards Through Intelligent Connections",meta:{client:"Microsoft Copilot",role:"Product Designer (7 weeks)",timeline:"2026",platform:"Desktop / Mobile / Web"},sections:[{id:"intro",layout:"sticky-split",stickyContent:{image:{src:"/assets/business-connectors/Connectors2.jpg",avif:"/assets/business-connectors/Connectors2.avif",webp:"/assets/business-connectors/Connectors2.webp",alt:"Business Connectors hero",aspectRatio:"16/9"},tags:["INTERACTION DESIGN","VISUAL DESIGN","PROTOTYPING","CROSS-PLATFORM"],collateralImages:[{src:"/assets/business-connectors/Connect AccountDrk.jpg",avif:"/assets/business-connectors/Connect AccountDrk.avif",webp:"/assets/business-connectors/Connect AccountDrk.webp",alt:"Target flow",aspectRatio:"16/9"},{src:"/assets/business-connectors/Password formDrk.jpg",avif:"/assets/business-connectors/Password formDrk.avif",webp:"/assets/business-connectors/Password formDrk.webp",alt:"Walmart flow",aspectRatio:"16/9"},{src:"/assets/business-connectors/Connection successful + Requery.jpg",avif:"/assets/business-connectors/Connection successful + Requery.avif",webp:"/assets/business-connectors/Connection successful + Requery.webp",alt:"Home Depot flow",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center top"},{src:"/assets/business-connectors/Perks Hover State.jpg",avif:"/assets/business-connectors/Perks Hover State.avif",webp:"/assets/business-connectors/Perks Hover State.webp",alt:"Nordstrom flow",aspectRatio:"5/3"},{src:"/assets/business-connectors/Settings Overlay 1.jpg",avif:"/assets/business-connectors/Settings Overlay 1.avif",webp:"/assets/business-connectors/Settings Overlay 1.webp",alt:"Generic hub",aspectRatio:"16/9"},{src:"/assets/business-connectors/Settings Overlay 2.jpg",avif:"/assets/business-connectors/Settings Overlay 2.avif",webp:"/assets/business-connectors/Settings Overlay 2.webp",alt:"Chat integration",aspectRatio:"16/9"}]},scrollContent:{blocks:[{type:"text",heading:"Overview",body:"Business Connectors in Microsoft Copilot empowers users to connect third-party business accounts to unlock loyalty perks, discounts, and curated offers across multiple merchants. By integrating these flows directly into Copilot, the assistant becomes proactive and helps users complete high-value tasks without leaving the experience."},{type:"image",images:[{src:"/assets/business-connectors/Carousel Cards + Connector UpsellDrk.jpg",avif:"/assets/business-connectors/Carousel Cards + Connector UpsellDrk.avif",webp:"/assets/business-connectors/Carousel Cards + Connector UpsellDrk.webp",alt:"Copilot connector hub",aspectRatio:"6/5"}]},{type:"text",heading:"My Role",body:"I took over the project after initial explorations and worked as the primary designer for 7 weeks, partnering with a senior designer, PMs, and engineers. I led interaction design, visual design, prototyping, and cross-platform flows for desktop, mobile, and Copilot browser surfaces while shaping both merchant-specific and generic connector experiences."},{type:"carousel",images:[{src:"/assets/business-connectors/Connect Account.jpg",avif:"/assets/business-connectors/Connect Account.avif",webp:"/assets/business-connectors/Connect Account.webp",alt:"Merchant flow screenshot 1",aspectRatio:"16/9"},{src:"/assets/business-connectors/Password form.jpg",avif:"/assets/business-connectors/Password form.avif",webp:"/assets/business-connectors/Password form.webp",alt:"Merchant flow screenshot 2",aspectRatio:"16/9"},{src:"/assets/business-connectors/Connection SuccessfulDrk.jpg",avif:"/assets/business-connectors/Connection SuccessfulDrk.avif",webp:"/assets/business-connectors/Connection SuccessfulDrk.webp",alt:"Merchant flow screenshot 3",aspectRatio:"16/9"},{src:"/assets/business-connectors/Connection Successful.jpg",avif:"/assets/business-connectors/Connection Successful.avif",webp:"/assets/business-connectors/Connection Successful.webp",alt:"Merchant flow screenshot 4",aspectRatio:"6/5"},{src:"/assets/business-connectors/PDP + Connector UpsellDrk.jpg",avif:"/assets/business-connectors/PDP + Connector UpsellDrk.avif",webp:"/assets/business-connectors/PDP + Connector UpsellDrk.webp",alt:"Merchant flow screenshot 5",aspectRatio:"16/9"}]},{type:"quote",body:"Enable frictionless connection of loyalty accounts across multiple merchants."}]}},{id:"parallax-hero",layout:"parallax-reveal",heading:"Merchant-Specific Flows",body:"Designed complete flows for Target, Walmart, Home Depot, and Nordstrom. Users connect accounts from chat prompts or product detail surfaces, then move through native sign-in with clear progress and confirmation.",images:[{src:"/assets/business-connectors/Connectors3.jpg",avif:"/assets/business-connectors/Connectors3.avif",webp:"/assets/business-connectors/Connectors3.webp",alt:"Merchant connection flow",aspectRatio:"16/9"}],parallaxSpeed:.35},{id:"design-goals",layout:"three-column-feature",heading:"Design Goals",labels:["FRICTIONLESS","AI-POWERED","CONSISTENT","SCALABLE"],body:"Enable frictionless connection of loyalty accounts across merchants, surface AI-powered value at the right moments, and maintain consistency while supporting each merchant's native login requirements.",images:[{src:"/assets/business-connectors/Inline Cards + Connector Upsell-1.jpg",avif:"/assets/business-connectors/Inline Cards + Connector Upsell-1.avif",webp:"/assets/business-connectors/Inline Cards + Connector Upsell-1.webp",alt:"Design system and goals feature",aspectRatio:"16/9"}],accentColor:"#e8ded2"},{id:"ai-interactions",layout:"image-on-color-block",heading:"AI-Integrated Interactions",body:'Designed streaming "thinking" animations as AI processes account connections, with real-time badge updates and reward states across chat and product cards. These interactions create clarity without overwhelming the user and reinforce trust in the assistant\'s recommendations.',images:[{src:"/assets/business-connectors/Inline Cards + Connector Upsell.jpg",avif:"/assets/business-connectors/Inline Cards + Connector Upsell.avif",webp:"/assets/business-connectors/Inline Cards + Connector Upsell.webp",alt:"AI thinking state",aspectRatio:"9/13"}],accentColor:"#d4e0ed"},{id:"details",layout:"staggered-pair",images:[{src:"/assets/business-connectors/Perks.jpg",avif:"/assets/business-connectors/Perks.avif",webp:"/assets/business-connectors/Perks.webp",alt:"Rewards badge",aspectRatio:"16/9"},{src:"/assets/business-connectors/Connector Settings 2.jpg",avif:"/assets/business-connectors/Connector Settings 2.avif",webp:"/assets/business-connectors/Connector Settings 2.webp",alt:"Product card integration",aspectRatio:"16/9"}]},{id:"reflection-quote",layout:"quote",body:"By reducing friction, personalizing interactions, and consolidating loyalty rewards, users gain real value — and Copilot creates a flywheel of engagement and trust.",heading:"Reflection",accentColor:"#333"},{id:"impact",layout:"text-only",heading:"Impact & Outcome",body:"Designs were approved by the Copilot council for flighting and established a scalable framework for connecting multiple merchant accounts inside Copilot. The work set a strong foundation for AI-native commerce by linking account connection, rewards intelligence, and trust-building interaction patterns across platforms.\n\nBy reducing connection friction and surfacing loyalty value at the right moments, Business Connectors makes Copilot more useful for real-world shopping decisions and long-term engagement."}]},{slug:"copilot-pay",title:"Copilot Pay",subtitle:"Designing Microsoft's first native checkout inside Copilot",coverImage:{src:"/assets/copilot-pay/Property 1=Default.jpg",avif:"/assets/copilot-pay/Property 1=Default.avif",webp:"/assets/copilot-pay/Property 1=Default.webp",alt:"Copilot Pay checkout experience",aspectRatio:"16/9"},heroImage:{src:"/assets/copilot-pay/PDP.jpg",avif:"/assets/copilot-pay/PDP.avif",webp:"/assets/copilot-pay/PDP.webp",alt:"Copilot Pay product detail page with native checkout",aspectRatio:"16/9",objectFit:"contain",objectPosition:"center center",backgroundColor:"#ffffff"},transitionImages:[{src:"/assets/copilot-pay/Property 1=Default.jpg",alt:"Copilot Pay transition 1"},{src:"/assets/copilot-pay/PDP.jpg",alt:"Copilot Pay transition 2"},{src:"/assets/copilot-pay/Copilot pay 1.jpg",alt:"Copilot Pay transition 3"},{src:"/assets/copilot-pay/Copilot pay 2.jpg",alt:"Copilot Pay transition 4"},{src:"/assets/copilot-pay/Copilot pay 3.jpg",alt:"Copilot Pay transition 5"}],heroHeadline:"Bringing frictionless native checkout to Copilot shopping",meta:{client:"Copilot Pay | Microsoft Shopping",role:"Designer (interaction, visual, prototyping, design system)",timeline:"7 weeks",platform:"Browser / Desktop / Mobile"},sections:[{id:"overview",layout:"sticky-split",stickyContent:{image:{src:"/assets/copilot-pay/Bang & Olufsen Dark.jpg",avif:"/assets/copilot-pay/Bang & Olufsen Dark.avif",webp:"/assets/copilot-pay/Bang & Olufsen Dark.webp",alt:"Bang & Olufsen checkout flow in dark mode",aspectRatio:"4/3",backgroundColor:"#0f1220",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},tags:["AI COMMERCE","PAYMENTS UX","CROSS-PLATFORM","DESIGN SYSTEM"],collateralImages:[{src:"/assets/copilot-pay/Copilot pay 1.jpg",avif:"/assets/copilot-pay/Copilot pay 1.avif",webp:"/assets/copilot-pay/Copilot pay 1.webp",alt:"Copilot Pay mobile express checkout flow",aspectRatio:"16/9",backgroundColor:"#E7E7E7",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/copilot-pay/Copilot pay 2.jpg",avif:"/assets/copilot-pay/Copilot pay 2.avif",webp:"/assets/copilot-pay/Copilot pay 2.webp",alt:"Copilot Pay payment method setup flow",aspectRatio:"16/9",backgroundColor:"#E7E7E7",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/copilot-pay/Apple express.jpg",avif:"/assets/copilot-pay/Apple express.avif",webp:"/assets/copilot-pay/Apple express.webp",alt:"Apple Pay express checkout flow",aspectRatio:"16/9",backgroundColor:"#E7E7E7",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/copilot-pay/Paypal express.jpg",avif:"/assets/copilot-pay/Paypal express.avif",webp:"/assets/copilot-pay/Paypal express.webp",alt:"PayPal express checkout flow",aspectRatio:"16/9",backgroundColor:"#E7E7E7",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"}]},scrollContent:{blocks:[{type:"text",heading:"Overview",body:"Copilot Pay is Microsoft's first native checkout inside Copilot across browser, desktop, and mobile. It surfaces Buy buttons on product cards and PDPs, then enables express checkout through Apple Pay, PayPal, Venmo, Google Pay, Shop Pay, and Amazon Pay. Before this work, users were redirected to retailer sites, which introduced friction and broke continuity."},{type:"text",heading:"Team & Role",body:"I worked with a principal designer, PM, and engineers over a 7 week sprint, leading interaction design, visual design, prototyping, and design system work. My focus was making native wallet checkout feel coherent inside Copilot while staying scalable across platforms and partner payment experiences."},{type:"carousel",images:[{src:"/assets/copilot-pay/card1.jpg",avif:"/assets/copilot-pay/card1.avif",webp:"/assets/copilot-pay/card1.webp",alt:"Copilot Pay recommendation card surface",aspectRatio:"16/9",backgroundColor:"#ffffff",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/copilot-pay/card2.jpg",avif:"/assets/copilot-pay/card2.avif",webp:"/assets/copilot-pay/card2.webp",alt:"Copilot Pay wallet selection modal",aspectRatio:"16/9",backgroundColor:"#ffffff",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/copilot-pay/card3.jpg",avif:"/assets/copilot-pay/card3.avif",webp:"/assets/copilot-pay/card3.webp",alt:"Copilot Pay order details and payment setup flow",aspectRatio:"16/9",backgroundColor:"#ffffff",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"}]},{type:"quote",body:"Enable frictionless checkout inside Copilot while standardizing visual and interaction patterns across native wallets."}]}},{id:"goals",layout:"three-column-feature",heading:"Goals",labels:["FRICTIONLESS","CONSISTENT","SCALABLE","AI COMMERCE"],body:"The project focused on keeping users inside Copilot through checkout, standardizing payment interactions across multiple wallet brands, and expanding Microsoft's AI commerce capabilities with a reusable foundation for future shopping flows.",images:[{src:"/assets/copilot-pay/Pay CMC Background + PDP.jpg",avif:"/assets/copilot-pay/Pay CMC Background + PDP.avif",webp:"/assets/copilot-pay/Pay CMC Background + PDP.webp",alt:"Copilot Pay desktop commerce experience",aspectRatio:"16/9",backgroundColor:"#ffffff"}],accentColor:"#e6f1ff"},{id:"responsibilities",layout:"text-only",heading:"Responsibilities",body:"Designed express checkout flows for desktop and mobile.\n\nCreated an intermediate screen showing all payment options before opening native wallets.\n\nEvaluated button placement above and below product info for usability across devices.\n\nRebuilt and expanded the Copilot Pay component library across product cards, carousels, PDP side panels, checkout sheets, input fields, order summary, confirmation pages, and payment icons.\n\nStandardized design tokens, spacing, typography, light and dark modes, and color consolidation.\n\nBuilt prototypes and internal specs to align the work with cross-team design standards."},{id:"wallet-systems",layout:"image-on-color-block",heading:"Designing Across Native Wallets",body:"One of the core challenges was integrating multiple native wallet experiences, each with different branding, affordances, and interaction expectations, without making Copilot feel fragmented. The solution was an intermediate selection screen and a tighter component system that kept the transition into each wallet legible and predictable.",images:[{src:"/assets/copilot-pay/Bang & Olufsen.jpg",avif:"/assets/copilot-pay/Bang & Olufsen.avif",webp:"/assets/copilot-pay/Bang & Olufsen.webp",alt:"Bang & Olufsen native checkout flow",aspectRatio:"16/9",backgroundColor:"#ffffff",borderRadius:"12px",containerBorder:"1px solid #d4d4d4",containerBorderRadius:"12px",containerShadow:"none",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"}],accentColor:"#f3efe7"},{id:"cross-platform",layout:"staggered-pair",images:[{src:"/assets/copilot-pay/Property 1=Default.jpg",avif:"/assets/copilot-pay/Property 1=Default.avif",webp:"/assets/copilot-pay/Property 1=Default.webp",alt:"Desktop Copilot Pay recommendation surface"},{src:"/assets/copilot-pay/Copilot pay 3.jpg",avif:"/assets/copilot-pay/Copilot pay 3.avif",webp:"/assets/copilot-pay/Copilot pay 3.webp",alt:"Mobile Copilot Pay multi-step checkout experience",aspectRatio:"16/9"}]},{id:"challenges",layout:"text-only",heading:"Challenges",body:"Multiple native wallet UIs introduced different branding and interaction patterns.\n\nDesktop and mobile needed to feel consistent without ignoring platform-specific constraints.\n\nThe component library needed to scale quickly while remaining reusable for future AI commerce scenarios.\n\nExpress checkout had to slot naturally into both product cards and PDPs without breaking the shopping flow."},{id:"express-variants",layout:"staggered-pair",heading:"Express checkout across brands",body:"Each express partner brought its own visual system. The intermediate selection screen and shared component foundation let Amazon, PayPal, and other wallets coexist inside Copilot without losing brand recognition or breaking the flow.",images:[{src:"/assets/copilot-pay/Amazon express.jpg",avif:"/assets/copilot-pay/Amazon express.avif",webp:"/assets/copilot-pay/Amazon express.webp",alt:"Amazon express checkout inside Copilot",aspectRatio:"16/9",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},{src:"/assets/copilot-pay/Paypal express2.jpg",avif:"/assets/copilot-pay/Paypal express2.avif",webp:"/assets/copilot-pay/Paypal express2.webp",alt:"PayPal express checkout variant inside Copilot",aspectRatio:"16/9",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"}]},{id:"impact",layout:"quote",heading:"Impact",body:"Copilot Pay establishes Microsoft's first frictionless native checkout inside Copilot, creates a robust design-system foundation for future AI-assisted commerce, and supports seamless shopping across Microsoft platforms with scalable, consistent components.",accentColor:"#222222"}]},{slug:"journeys",title:"Journeys",subtitle:"My Shopping for Microsoft Shopping",coverImage:{src:"/assets/journeys/Journeys L2.jpg",avif:"/assets/journeys/Journeys L2.avif",webp:"/assets/journeys/Journeys L2.webp",alt:"Journeys dashboard with personalized shopping modules",aspectRatio:"16/9"},heroImage:{src:"/assets/journeys/Journeys L2.jpg",avif:"/assets/journeys/Journeys L2.avif",webp:"/assets/journeys/Journeys L2.webp",alt:"Journeys dashboard with personalized shopping modules",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center"},transitionImages:[{src:"/assets/journeys/Browser wrapper.jpg",alt:"Journeys landing experience in Microsoft Shopping"},{src:"/assets/journeys/102.jpg",alt:"Journeys shopping dashboard with notifications and resume-shopping modules"},{src:"/assets/journeys/Shopping toast notification4.jpg",alt:"Journeys shopping notification toast surfaced on Windows"},{src:"/assets/journeys/202.jpg",alt:"Journeys shopping layout with style inspiration and shopping modules"},{src:"/assets/journeys/Saved products high information layout.jpg",alt:"Journeys saved products module with retailer comparisons"}],heroHeadline:"Designing a calmer shopping hub around real user journeys",meta:{client:"My Shopping / Journeys | Microsoft Shopping",role:"Mid-level designer partnering with a principal designer",timeline:"Placeholder case study",platform:"Browser / Copilot / Microsoft ecosystem"},sections:[{id:"overview",layout:"sticky-split",stickyContent:{fullBleedImage:!0,image:{src:"/assets/journeys/Browser wrapper.jpg",avif:"/assets/journeys/Browser wrapper.avif",webp:"/assets/journeys/Browser wrapper.webp",alt:"Journeys landing experience in Microsoft Shopping",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center"},tags:["SHOPPING UX","PERSONALIZATION","AI COMMERCE","SYSTEM THINKING"],collateralImages:[{src:"/assets/journeys/Cold start.jpg",avif:"/assets/journeys/Cold start.avif",webp:"/assets/journeys/Cold start.webp",alt:"Journeys onboarding flow for following favorite stores",aspectRatio:"16/9",backgroundColor:"#f6f8fc",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/journeys/Connecting.jpg",avif:"/assets/journeys/Connecting.avif",webp:"/assets/journeys/Connecting.webp",alt:"Journeys account connection loading state",aspectRatio:"16/9",backgroundColor:"#f6f8fc",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/journeys/My profile.jpg",avif:"/assets/journeys/My profile.avif",webp:"/assets/journeys/My profile.webp",alt:"Journeys account connections and profile management",aspectRatio:"16/9",backgroundColor:"#f6f8fc",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"},{src:"/assets/journeys/User launches Edge browser to see recommended product3.jpg",alt:"Journeys product detail experience with browser-side shopping recommendations",aspectRatio:"16/9",backgroundColor:"#f6f8fc",imagePaddingBlock:"clamp(0.5rem, 1.2vw, 0.875rem)",objectFit:"contain",objectPosition:"center center"}]},scrollContent:{blocks:[{type:"text",heading:"Problem",body:"Online shopping involves multiple steps, platforms, and mental load. Users struggle to track their activity across products, retailers, and categories, and often feel uncertain about purchases, price drops, deals, and product discovery. The challenge was to create a central hub that simplifies shopping, helps users save money, and surfaces insights tailored to where they are in the journey."},{type:"text",heading:"Role & Collaboration",body:"I collaborated with a principal designer as a mid-level designer on this project. My work included designing three user flow scenarios, interaction models, and feed-based versus static hub layouts. I worked closely with PMs, engineers, and researchers to prototype and iterate while keeping the experience calm, visually clear, and practical."},{type:"text",heading:"Approach & Features",body:"We defined three journey stages. Early focused on discovery with highlights from recent activity, curated recommendations, insights on new brands or categories, recently viewed products, and buying guides. Mid focused on narrowing choices with price drops, top options with reasoning, product comparisons, tracked items, and store recommendations. Late and post-purchase focused on package tracking, pending cashback, complementary recommendations, Copilot prompts, and routine guides.\n\nKey features I designed included activity summaries, recommendations with filters, insights modules, recently viewed items, buying guides, cashback and deals integration, and Copilot-powered chat prompts for follow-up questions. Feed-based layouts helped disperse dense information into a format that felt more digestible and easier to trust."},{type:"quote",body:"The work explored how a browser can surface holistic shopping intelligence that retailers alone cannot provide."}]}},{id:"discovery-entry-surface",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/journeys/Exploration 5.jpg",avif:"/assets/journeys/Exploration 5.avif",webp:"/assets/journeys/Exploration 5.webp",alt:"Journeys exploration surface with discovery cards and notifications",aspectRatio:"16/9"}]},{id:"journey-stages",layout:"three-column-feature",heading:"Journey Stages",labels:["EARLY","MID","LATE / POST-PURCHASE"],body:"Journeys was structured around changing user intent. The system shifts from exploration and inspiration, to comparison and confidence-building, to post-purchase tracking and support. That framing made it possible to prioritize the right content at the right moment instead of treating shopping like one generic feed.",images:[{src:"/assets/journeys/Returning user5.jpg",alt:"Journeys returning user view with personalized shopping context",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center"}],accentColor:"#dce8ff"},{id:"recent-activity-surface",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/journeys/Journeys L22.jpg",avif:"/assets/journeys/Journeys L22.avif",webp:"/assets/journeys/Journeys L22.webp",alt:"Journeys recently viewed surface with category and product ranking",aspectRatio:"16/9"}]},{id:"feed-based-clarity",layout:"image-on-color-block",heading:"Feed-Based Clarity",body:"A core design decision was testing feed-based layouts against more static hub models. The feed approach made recommendations, insights, tracked products, and follow-up prompts feel visually dispersed and easier to scan, which helped balance information density with clarity and reduced the sense of promotional overload.",images:[{src:"/assets/journeys/High information layout6.jpg",avif:"/assets/journeys/High information layout6.avif",webp:"/assets/journeys/High information layout6.webp",alt:"Journeys high-information feed layout with dense recommendation modules",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center"}],accentColor:"#edf5ff"},{id:"exploration-surface",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/journeys/Journeys L23.jpg",avif:"/assets/journeys/Journeys L23.avif",webp:"/assets/journeys/Journeys L23.webp",alt:"Journeys exploration feed with category-led shopping discovery",aspectRatio:"16/9"}]},{id:"purchase-support-surface",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/journeys/Journeys L26.jpg",avif:"/assets/journeys/Journeys L26.avif",webp:"/assets/journeys/Journeys L26.webp",alt:"Journeys purchase support view with savings and delivery insights",aspectRatio:"16/9"}]},{id:"outcome",layout:"text-only",heading:"Outcome",body:"The project was never flighted in Bing, but it informed the Journeys flows that later shipped in Microsoft Copilot. The work reinforced a broader product lesson: meaningful shopping assistance comes from combining content, context, and AI-driven insights in ways that do not look or behave like traditional retail surfaces.\n\n    The case study now highlights key frames from onboarding, account connection, personalized feeds, and saved-product management so the story reads as a connected system rather than a single static screen."}]},{slug:"cashback-hub",title:"Cashback Hub",subtitle:"Cashback Hub & Edge Shoreline — Microsoft Shopping",coverImage:{src:"/assets/cashback-hub/hero.jpg",avif:"/assets/cashback-hub/hero.avif",webp:"/assets/cashback-hub/hero.webp",alt:"Microsoft Shopping Cashback Hub overview",aspectRatio:"16/9",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},heroImage:{src:"/assets/cashback-hub/hero.jpg",avif:"/assets/cashback-hub/hero.avif",webp:"/assets/cashback-hub/hero.webp",alt:"Microsoft Shopping Cashback Hub overview",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},transitionImages:[{src:"/assets/cashback-hub/hero.jpg",alt:"Cashback Hub overview"},{src:"/assets/cashback-hub/Activated offers.jpg",alt:"Activated cashback offers"},{src:"/assets/cashback-hub/3x day.jpg",alt:"Triple Cashback Tuesday campaign"}],heroHeadline:"Bringing clarity to cashback across Microsoft Shopping and Edge",meta:{client:"Microsoft Shopping",role:"Product Designer — interaction, visual, and cross-platform design",timeline:"Multi-quarter program",platform:"Web / Edge / Mobile"},sections:[{id:"overview",layout:"sticky-split",stickyContent:{image:{src:"/assets/cashback-hub/Redesign.jpg",avif:"/assets/cashback-hub/Redesign.avif",webp:"/assets/cashback-hub/Redesign.webp",alt:"Cashback Hub redesign — headline frame",aspectRatio:"5/4",objectFit:"cover",objectPosition:"center top",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},tags:["INTERACTION DESIGN","VISUAL DESIGN","CROSS-PLATFORM","DESIGN SYSTEMS"],collateralImages:[{src:"/assets/cashback-hub/Maximized.jpg",avif:"/assets/cashback-hub/Maximized.avif",webp:"/assets/cashback-hub/Maximized.webp",alt:"Maximized hub view — activity summary",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center",borderRadius:"0"},{src:"/assets/cashback-hub/Maximized2.jpg",avif:"/assets/cashback-hub/Maximized2.avif",webp:"/assets/cashback-hub/Maximized2.webp",alt:"Maximized hub view — transactions",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center",borderRadius:"0"},{src:"/assets/cashback-hub/Maximized3.jpg",avif:"/assets/cashback-hub/Maximized3.avif",webp:"/assets/cashback-hub/Maximized3.webp",alt:"Maximized hub view — account summary",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center",borderRadius:"0"},{src:"/assets/cashback-hub/Stores L2.jpg",avif:"/assets/cashback-hub/Stores L2.avif",webp:"/assets/cashback-hub/Stores L2.webp",alt:"Stores Level 2 merchant grid",aspectRatio:"7680/11696",objectFit:"cover",objectPosition:"top center",borderRadius:"0"},{src:"/assets/cashback-hub/Deals hub Proposed Design.jpg",avif:"/assets/cashback-hub/Deals hub Proposed Design.avif",webp:"/assets/cashback-hub/Deals hub Proposed Design.webp",alt:"Deals hub proposed redesign",aspectRatio:"7680/11696",objectFit:"cover",objectPosition:"top center",borderRadius:"0"},{src:"/assets/cashback-hub/11.jpg",avif:"/assets/cashback-hub/11.avif",webp:"/assets/cashback-hub/11.webp",alt:"Cashback hub composition study",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center",borderRadius:"0"}]},scrollContent:{blocks:[{type:"text",heading:"Overview",body:"The Cashback Hub lets users track, manage, and redeem cashback rewards across Microsoft Shopping surfaces. I led end-to-end design — interaction, visual, and cross-platform layouts — for the full hub, stores search, interstitial pages, and the Edge Shoreline companion pane. The goal was a clear, trustworthy, and engaging experience that aligned with Microsoft branding and the constraints of every surface it appeared on."},{type:"text",heading:"Problem",body:"Users struggled to understand the cashback journey. They didn't always know whether rewards were activated, pending, or redeemable, and the delayed payout system of up to sixty days caused confusion. Existing dashboards were unclear, lacked hierarchy, and didn't surface actionable next steps."},{type:"text",heading:"Role & Collaboration",body:"I owned design end-to-end and partnered with PMs, engineers, and researchers across Microsoft Shopping, Edge, and Windows. The work spanned interaction patterns, motion, copy, iconography, and visual language — bringing the hub, stores search, the Edge Shoreline pane, and seasonal campaigns under one consistent system."}]}},{id:"onboarding-light",layout:"full-width-image",heading:"Joining the program",body:"Onboarding had to set expectations about how cashback actually works — rewards activate when users shop through Microsoft Shopping and pay out after a confirmation window. Light and dark variants were tuned for Windows, Edge, and web surfaces.",images:[{src:"/assets/cashback-hub/Join Now.jpg",avif:"/assets/cashback-hub/Join Now.avif",webp:"/assets/cashback-hub/Join Now.webp",alt:"Cashback Join Now flow — light",aspectRatio:"5/8",objectFit:"cover",objectPosition:"top center",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"}]},{id:"onboarding-dark",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/cashback-hub/Join Now Dark.jpg",avif:"/assets/cashback-hub/Join Now Dark.avif",webp:"/assets/cashback-hub/Join Now Dark.webp",alt:"Cashback Join Now flow — dark",aspectRatio:"5/8",objectFit:"cover",objectPosition:"top center"}]},{id:"signed-in",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/cashback-hub/Signedin.jpg",avif:"/assets/cashback-hub/Signedin.avif",webp:"/assets/cashback-hub/Signedin.webp",alt:"Signed-in cashback hub experience",aspectRatio:"16/9"}]},{id:"activated-rewards",layout:"image-on-color-block",heading:"Activated rewards, clearer status",body:"Status hierarchy was the core of the redesign. The hub surfaces activated, pending, and redeemable rewards with consistent terminology and color so users always know where each reward sits — and what to do next.",images:[{src:"/assets/cashback-hub/Activated offers.jpg",avif:"/assets/cashback-hub/Activated offers.avif",webp:"/assets/cashback-hub/Activated offers.webp",alt:"Activated cashback offers surface",aspectRatio:"7/5",objectFit:"cover",objectPosition:"center top"}],accentColor:"#eef4ff"},{id:"pending-redemption-pair",layout:"staggered-pair",heading:"From pending to redeemed",body:"A delayed-payout system of up to sixty days needed careful interstitial design. Awaiting and redemption states explain what's happening, why, and when funds will be available — without burying users in fine print.",images:[{src:"/assets/cashback-hub/Awaiting confirmation.jpg",avif:"/assets/cashback-hub/Awaiting confirmation.avif",webp:"/assets/cashback-hub/Awaiting confirmation.webp",alt:"Awaiting confirmation state for pending cashback",aspectRatio:"7/5",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},{src:"/assets/cashback-hub/Redemption flow.jpg",avif:"/assets/cashback-hub/Redemption flow.avif",webp:"/assets/cashback-hub/Redemption flow.webp",alt:"Cashback redemption flow",aspectRatio:"16/9",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"}]},{id:"edge-shoreline",layout:"image-on-color-block",heading:"Edge Shoreline pane",body:"A compact companion view for browsing sessions shows activation status and guides users to merchants without leaving the page they're shopping on. Designed to feel native to Edge while keeping the full hub one click away.",images:[{src:"/assets/cashback-hub/Shoreline cash back tab.jpg",avif:"/assets/cashback-hub/Shoreline cash back tab.avif",webp:"/assets/cashback-hub/Shoreline cash back tab.webp",alt:"Edge Shoreline companion pane — cashback tab",aspectRatio:"16/9",objectFit:"cover",objectPosition:"center center"}],accentColor:"#f5f0ff"},{id:"stores-search-pair",layout:"staggered-pair",heading:"Stores search page",body:"Search results balance dense merchant data with scannable hierarchy. Cards surface percentage, category, and activation state — and the layout adapts cleanly between light and dark modes.",images:[{src:"/assets/cashback-hub/Stores search page.jpg",avif:"/assets/cashback-hub/Stores search page.avif",webp:"/assets/cashback-hub/Stores search page.webp",alt:"Stores search results — light",aspectRatio:"11/12",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"},{src:"/assets/cashback-hub/Stores search page Dark.jpg",avif:"/assets/cashback-hub/Stores search page Dark.avif",webp:"/assets/cashback-hub/Stores search page Dark.webp",alt:"Stores search results — dark",aspectRatio:"11/12",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"}]},{id:"campaigns-light",layout:"full-width-image",heading:"Triple Cashback Tuesday",body:"Campaign banners had to read as exciting without breaking trust. Triple Cashback Tuesday uses bold typography, focused color, and clear value props — translating cleanly across desktop and mobile entry points.",images:[{src:"/assets/cashback-hub/3x day.jpg",avif:"/assets/cashback-hub/3x day.avif",webp:"/assets/cashback-hub/3x day.webp",alt:"Triple Cashback Tuesday — light",aspectRatio:"1/1",objectFit:"cover",objectPosition:"top center",containerBorder:"1px solid rgba(15, 23, 42, 0.08)"}]},{id:"campaigns-dark",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/cashback-hub/3x day Dark.jpg",avif:"/assets/cashback-hub/3x day Dark.avif",webp:"/assets/cashback-hub/3x day Dark.webp",alt:"Triple Cashback Tuesday — dark",aspectRatio:"1/1",objectFit:"cover",objectPosition:"top center"}]},{id:"process-impact-takeaways",layout:"text-only",heading:"Process, impact & takeaways",body:"Research clarified pain points around delayed cashback awareness, and close collaboration with engineering kept the design scalable and responsive across multiple form factors. Iconography, color, and interaction patterns were aligned with Windows and Edge while preserving Microsoft Shopping's brand integrity.\n\nThe redesign improved user understanding of the cashback journey, reduced confusion around activation, pending, and redeemable states, and increased trust and engagement with featured promotions. The patterns we built around status, terminology, and next-step guidance now travel with cashback wherever it shows up across Microsoft Shopping — including the upcoming Copilot integration.\n\nThe biggest takeaway: clarity in financial interactions is non-negotiable. Balancing platform constraints while designing cross-surface experiences that scale from compact panes to full-page hubs forced a tighter design language, and that language is what makes the program feel coherent today."}]},{slug:"video-commerce",title:"Video Commerce",subtitle:"Bringing live and short-form video into the Bing shopping ecosystem",coverImage:{src:"/assets/video-commerce/Full Frame.jpg",avif:"/assets/video-commerce/Full Frame.avif",webp:"/assets/video-commerce/Full Frame.webp",alt:"Video commerce destination — full frame composition",aspectRatio:"16/9"},transitionImages:[{src:"/assets/video-commerce/1.jpg",alt:"Transition 1 — video shopping destination"},{src:"/assets/video-commerce/Components.jpg",alt:"Transition 2 — component system"},{src:"/assets/video-commerce/Frame 63343564.jpg",alt:"Transition 3 — video player frame"},{src:"/assets/video-commerce/Frame 63343572.jpg",alt:"Transition 4 — video commerce frame"},{src:"/assets/video-commerce/Frame 63343574.jpg",alt:"Transition 5 — multi-SKU exploration"}],heroHeadline:"Designing live and short-form video commerce across Bing, MSN, and Microsoft Start",meta:{client:"Microsoft Bing Shopping",role:"Lead Product Designer",timeline:"2024",platform:"Desktop / Mobile / Web"},sections:[{id:"intro",layout:"sticky-split",stickyContent:{image:{src:"/assets/video-commerce/Shopping Homepage.jpg",avif:"/assets/video-commerce/Shopping Homepage.avif",webp:"/assets/video-commerce/Shopping Homepage.webp",alt:"Bing Shopping homepage with video commerce entry points",aspectRatio:"9/8",objectFit:"contain",backgroundColor:"#ffffff",containerBorder:"1px solid #d1d5db"},tags:["PRODUCT DESIGN","INTERACTION DESIGN","VIDEO COMMERCE","CROSS-PLATFORM"],collateralImages:[{src:"/assets/video-commerce/Bing Search.jpg",avif:"/assets/video-commerce/Bing Search.avif",webp:"/assets/video-commerce/Bing Search.webp",alt:"Bing Search entry point for video shopping",aspectRatio:"16/9"},{src:"/assets/video-commerce/Edge NTP - Roposo Live Shopping Entry Point.jpg",avif:"/assets/video-commerce/Edge NTP - Roposo Live Shopping Entry Point.avif",webp:"/assets/video-commerce/Edge NTP - Roposo Live Shopping Entry Point.webp",alt:"Edge new tab page entry point for Roposo live shopping",aspectRatio:"16/9"},{src:"/assets/video-commerce/MSN - Roposo Live Shopping Entry Point.jpg",avif:"/assets/video-commerce/MSN - Roposo Live Shopping Entry Point.avif",webp:"/assets/video-commerce/MSN - Roposo Live Shopping Entry Point.webp",alt:"MSN entry point for Roposo live shopping",aspectRatio:"16/9"},{src:"/assets/video-commerce/Bing Search - Roposo Live Shopping Entry point.jpg",avif:"/assets/video-commerce/Bing Search - Roposo Live Shopping Entry point.avif",webp:"/assets/video-commerce/Bing Search - Roposo Live Shopping Entry point.webp",alt:"Bing Search entry point for Roposo live shopping",aspectRatio:"16/9"}]}},{id:"strategic-hypothesis",layout:"text-only",heading:"Strategic Hypothesis",body:"Asian markets have strong adoption of live shopping and short-form video commerce. Leadership believed similar models could enhance Bing's shopping experience by providing richer qualitative product education, increasing engagement and session duration, introducing trusted creator-driven reviews instead of purely corporate messaging, and expanding the shopping funnel beyond static product listings.\n\nThis was positioned as a moonshot exploration with international pilots in the U.S., Japan, and India."},{id:"partners",layout:"full-width-image",heading:"Partner Integrations & International Expansion",body:"We collaborated with TalkShopLive for U.S. live commerce via an embedded third-party player, QVC Japan for the Japan pilot, and InMobi via Roposo for an India short-form pilot.\n\nEach partner delivered different video formats, metadata structures, and localization requirements. We explored mapping YouTube product review content to Bing Product IDs and normalizing video-to-product relationships across platforms.\n\nTalkShopLive required embedding their existing video player, limiting our control to surrounding UI and entry points. For InMobi, we had full control and designed a more integrated video player experience.",images:[{src:"/assets/video-commerce/TSL Feed Experience.jpg",avif:"/assets/video-commerce/TSL Feed Experience.avif",webp:"/assets/video-commerce/TSL Feed Experience.webp",alt:"TalkShopLive feed experience integration",aspectRatio:"7/5",containerBorder:"1px solid #e5e7eb"}]},{id:"tsl-msn",layout:"full-width-image",sectionBackground:"#ffffff",heading:"TalkShopLive in MSN Watch",body:"Embedded TalkShopLive within the MSN Watch experience, designing the surrounding UI, entry points, and product context to integrate the third-party player into a Microsoft surface.",images:[{src:"/assets/video-commerce/TalkShopLive in MSN _Watch_ experience.jpg",avif:"/assets/video-commerce/TalkShopLive in MSN _Watch_ experience.avif",webp:"/assets/video-commerce/TalkShopLive in MSN _Watch_ experience.webp",alt:"TalkShopLive embedded within MSN Watch experience",aspectRatio:"3/4",objectFit:"contain",mixBlendMode:"multiply"}]},{id:"multi-sku-exploration",layout:"full-width-image",sectionBackground:"#f5f5f5",heading:"Designing for Multi-SKU Video Commerce",body:"A core challenge was that many videos featured multiple products.\n\nWe initially explored a glass-effect overlay product panel layered on top of the video. While immersive, this approach introduced cognitive load and visual competition — especially when combined with chat and live indicators.",images:[{src:"/assets/video-commerce/Transparent Black.jpg",avif:"/assets/video-commerce/Transparent Black.avif",webp:"/assets/video-commerce/Transparent Black.webp",alt:"Early glass-effect overlay product panel exploration",aspectRatio:"16/9"}]},{id:"pdp-overlay",layout:"full-width-image",disableCompactPadding:!0,images:[{src:"/assets/video-commerce/PDP Popup - option 2.jpg",avif:"/assets/video-commerce/PDP Popup - option 2.avif",webp:"/assets/video-commerce/PDP Popup - option 2.webp",alt:"PDP popup overlay exploration — option 2",aspectRatio:"5/4"}]},{id:"docked-solution",layout:"image-on-color-block",heading:"Docked Product Panel",body:"We ultimately transitioned to a docked product panel positioned beside the video. This reduced obstruction of video content, improved SKU scannability, created stronger visual hierarchy, and lowered interaction friction compared to dismissible overlays.",images:[{src:"/assets/video-commerce/ShopThing Video Page -tooltip- 540px video height.jpg",avif:"/assets/video-commerce/ShopThing Video Page -tooltip- 540px video height.avif",webp:"/assets/video-commerce/ShopThing Video Page -tooltip- 540px video height.webp",alt:"Docked product panel beside video with tooltip — 540px video height",aspectRatio:"16/9"}],accentColor:"#d4e0ed"},{id:"mobile-hierarchy",layout:"staggered-pair",heading:"Mobile Hierarchy",body:"On mobile, hierarchy was simplified to preserve clarity and avoid stacking competing interactive elements. The product panel collapses into a focused commerce strip below the video, keeping the creator's content primary while keeping product context one tap away.",images:[{src:"/assets/video-commerce/Mobile.jpg",avif:"/assets/video-commerce/Mobile.avif",webp:"/assets/video-commerce/Mobile.webp",alt:"Mobile video commerce hierarchy",aspectRatio:"16/9"},{src:"/assets/video-commerce/UX Mobile Experience 1.jpg",avif:"/assets/video-commerce/UX Mobile Experience 1.avif",webp:"/assets/video-commerce/UX Mobile Experience 1.webp",alt:"Mobile UX experience with simplified hierarchy",aspectRatio:"1/1",objectPosition:"top"}]},{id:"live-engagement",layout:"image-on-color-block",heading:"Live Commerce & Engagement",body:'To differentiate live streams from recorded content, I designed a pulsing red live badge aligned with established live-stream conventions. The motion was subtle but intentional, reinforcing urgency while minimizing distraction.\n\nWe also integrated live chat functionality within the video player to support creator-viewer interaction and strengthen authenticity. An "Upcoming Shows" rail surfaced scheduled events to encourage repeat visits and deeper engagement.',images:[{src:"/assets/video-commerce/Night Mode Feeds 2.0 Color Gradient + BG Shapes.jpg",avif:"/assets/video-commerce/Night Mode Feeds 2.0 Color Gradient + BG Shapes.avif",webp:"/assets/video-commerce/Night Mode Feeds 2.0 Color Gradient + BG Shapes.webp",alt:"Night mode feed with live badge, chat, and engagement surfaces",aspectRatio:"16/9"}],accentColor:"#1a1a1a"},{id:"roposo-india",layout:"full-width-image",heading:"Roposo — India Pilot",body:"For the InMobi / Roposo India short-form pilot we had full control over the player and designed an integrated video commerce experience tuned for short-form discovery.",images:[{src:"/assets/video-commerce/Roposo.jpg",avif:"/assets/video-commerce/Roposo.avif",webp:"/assets/video-commerce/Roposo.webp",alt:"Roposo short-form video commerce pilot — India",aspectRatio:"1/1"}]},{id:"native-player",layout:"full-width-image",heading:"Native Player Exploration",body:"Recognizing the risks of third-party dependency and contract-based timelines (1–2 year agreements), we began designing a first-party native video player to gain full control over interaction design and product integration.\n\nWhile foundational design work was completed, the native player did not launch before contracts expired. Shortly after, a leadership transition resulted in a strategic pivot and the retirement of the initiative.",images:[{src:"/assets/video-commerce/Frame 63343577.jpg",avif:"/assets/video-commerce/Frame 63343577.avif",webp:"/assets/video-commerce/Frame 63343577.webp",alt:"First-party native video player exploration",aspectRatio:"5/2"}]},{id:"reflection-quote",layout:"quote",heading:"Reflection",body:"Designing through ambiguity, integrating multiple third-party systems, and navigating shifting executive priorities taught me how to balance entertainment and commerce in a dense interface — and how to design for platform dependencies you don't fully control.",accentColor:"#333"},{id:"impact",layout:"text-only",heading:"Impact & Learnings",body:"Although the project was ultimately discontinued, it established cross-market experimentation in the U.S., Japan, and India, a scalable video component system across shopping surfaces, and a framework for mapping video content to structured product data.\n\nIt also produced design approaches for balancing entertainment and commerce in a dense interface, and lessons in platform dependency, contract risk, and executive-driven innovation cycles. The work required designing through ambiguity, integrating multiple third-party systems, navigating shifting executive priorities, and balancing engagement with usability in a highly complex UI environment."}]},{slug:"ironlak-internship",title:"Ironlak Internship",subtitle:"A multilingual brand identity system and three months of production design for an Australian spray paint company",coverImage:{src:"/assets/ironlak-internship/IronlakAdvert2.jpg",avif:"/assets/ironlak-internship/IronlakAdvert2.avif",webp:"/assets/ironlak-internship/IronlakAdvert2.webp",alt:"Ironlak brand campaign — multilingual wordmark composition",aspectRatio:"4/3",objectFit:"contain"},transitionImages:[{src:"/assets/ironlak-internship/IronlakAdvert2.jpg",alt:"Transition 1 — Ironlak advert"},{src:"/assets/ironlak-internship/Group 55614@2x.png",alt:"Transition 2 — multilingual wordmark system"},{src:"/assets/ironlak-internship/IronlakPoster1.jpg",alt:"Transition 3 — Ironlak poster"},{src:"/assets/ironlak-internship/MaintainBBQburners.jpg",alt:"Transition 4 — Maintain BBQ Burners flyer"},{src:"/assets/ironlak-internship/BillboardIronlak.jpg",alt:"Transition 5 — Ironlak billboard"}],heroHeadline:"A multilingual identity system for Ironlak, and three months designing production work for a brand I grew up on",meta:{client:"Ironlak (Australia)",role:"Brand Identity & Production Design Intern",timeline:"2017",platform:"Print / Digital / Outdoor"},sections:[{id:"intro",layout:"sticky-split",stickyContent:{image:{src:"/assets/ironlak-internship/Group 55614@2x.png",avif:"/assets/ironlak-internship/Group 55614@2x.avif",webp:"/assets/ironlak-internship/Group 55614@2x.webp",alt:"Multilingual Ironlak wordmark system",aspectRatio:"1/1",objectFit:"contain",backgroundColor:"#ffffff",containerBorder:"1px solid #d1d5db",imagePaddingBlock:"6rem",imagePaddingInline:"4rem"},tags:["BRAND IDENTITY","PRODUCTION DESIGN","ILLUSTRATION","PRINT"]}},{id:"background",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"3.75rem 0 0.5rem",heading:"Background",body:"My relationship with graffiti goes back to 2006, and it is a passion I have never put down. So when I was a senior in school looking for a real-world brand challenge, Ironlak felt like a natural fit. An Australian spray paint company built by and for graffiti artists, they were a brand I genuinely believed in. I cold-emailed them with a concept, and what started as a school project eventually turned into a three-month internship."},{id:"problem",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"0.5rem 0",heading:"The Problem",body:"Ironlak wanted to grow beyond its existing audience and connect with artists and communities across the globe. The challenge was building a visual identity that could feel authentic to graffiti culture while speaking to people from entirely different backgrounds, languages, and continents."},{id:"insight",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"0.5rem 0",heading:"The Insight",body:"Research led to a simple but powerful idea. Mark-making is one of the oldest universal human impulses. From Aboriginal Australian cave paintings to Sumerian cuneiform to Arabic calligraphy, every culture has its own visual language. Graffiti, at its core, is just the latest chapter in that tradition. If the identity could tap into that universality, the brand could feel at home anywhere in the world."},{id:"concept",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"0.5rem 0 3.75rem",heading:"The Concept",body:'The solution was a modular wordmark system built around language itself. I translated the word "Iron" into over fifteen languages including Japanese, Hebrew, Arabic, Greek, Russian, Korean, Dutch, French, Albanian, Italian, Bosnian, Irish, Swedish, Latvian, Catalan, and Finnish, while keeping "LAK" constant across every version.\n\nEach mark felt culturally specific on top but unified at its base. A bold red LAK block anchored every version, with the translated word above it rendered in a style native to each script. The brand could speak to someone in Tokyo the same way it spoke to someone in Dublin.'},{id:"system-applications-carousel",layout:"image-carousel",images:[{src:"/assets/ironlak-internship/IronlakPoster1.jpg",avif:"/assets/ironlak-internship/IronlakPoster1.avif",webp:"/assets/ironlak-internship/IronlakPoster1.webp",alt:"Ironlak poster — series 1",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/IronlakPoster2.jpg",avif:"/assets/ironlak-internship/IronlakPoster2.avif",webp:"/assets/ironlak-internship/IronlakPoster2.webp",alt:"Ironlak poster — series 2",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/IronlakPoster4.jpg",avif:"/assets/ironlak-internship/IronlakPoster4.avif",webp:"/assets/ironlak-internship/IronlakPoster4.webp",alt:"Ironlak poster — series 4",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/IronlakPoster3.jpg",avif:"/assets/ironlak-internship/IronlakPoster3.avif",webp:"/assets/ironlak-internship/IronlakPoster3.webp",alt:"Ironlak poster — series 3",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/Group 55616@2x.png",avif:"/assets/ironlak-internship/Group 55616@2x.avif",webp:"/assets/ironlak-internship/Group 55616@2x.webp",alt:"Ironlak branded sweaters",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/IronlakMockup.jpg",avif:"/assets/ironlak-internship/IronlakMockup.avif",webp:"/assets/ironlak-internship/IronlakMockup.webp",alt:"Ironlak campaign mockup",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/GreekShirtcrop.jpg",avif:"/assets/ironlak-internship/GreekShirtcrop.avif",webp:"/assets/ironlak-internship/GreekShirtcrop.webp",alt:"Greek-language Ironlak apparel application",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/BillboardIronlak.jpg",avif:"/assets/ironlak-internship/BillboardIronlak.avif",webp:"/assets/ironlak-internship/BillboardIronlak.webp",alt:"Large-format Ironlak billboard application",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/billboardIronlak2.jpg",avif:"/assets/ironlak-internship/billboardIronlak2.avif",webp:"/assets/ironlak-internship/billboardIronlak2.webp",alt:"Large-format Ironlak billboard — alternate composition",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"}]},{id:"system-applications",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"3.75rem 0 0.5rem",heading:"System Applications",body:"Once the core mark was finalized, the identity was extended across a full brand world — stationery, promotional posters, product packaging, web and mobile interface mockups, branded merchandise, large-format outdoor advertising, and animation storyboarding. Each application showed how the multilingual system could flex across contexts without losing its visual cohesion."},{id:"process",layout:"text-only",sectionBackground:"#f5f5f5",sectionPadding:"0.5rem 0 3.75rem",heading:"Process",body:"The work began with verbal brainstorming, building out what graffiti means as a cultural force — energy, legacy, universality, dedication, craft. From there I gathered visual inspiration from street art, ancient scripts, and mark-making traditions across history.\n\nEarly mark development happened by hand, using Sharpie sketches to explore letterforms and tagging styles before moving into digital execution. In Illustrator I explored 3D rendering, hand-lettered graffiti aesthetics, and clean typographic treatments across all the language variants, testing how each script could carry the system while still feeling true to its own visual culture."},{id:"process-image",layout:"full-width-image",sectionPadding:"3.75rem 0 0",images:[{src:"/assets/ironlak-internship/Group 55615@2x.png",avif:"/assets/ironlak-internship/Group 55615@2x.avif",webp:"/assets/ironlak-internship/Group 55615@2x.webp",alt:"Ironlak ad layout exploration",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"6rem",imagePaddingBlock:"4rem"}]},{id:"the-internship",layout:"text-only",sectionBackground:"#ffffff",sectionPadding:"1rem 0 3.75rem",heading:"The Internship",body:"Presenting the full system to Ironlak led directly to a three-month internship with the company. The day-to-day work was grounded in real production across print, digital, and social formats. I designed ads, social media posts, and small promotional cards for Ironlak and several of the spray paint shops they partnered with."},{id:"bbq-burners",layout:"image-on-color-block",sectionBackground:"#f5f5f5",heading:"BBQ Burners",body:"A significant part of the internship was creating flyers for BBQ Burner events — community gatherings where spray paint shops host artists for a day or two of painting, food, and drinks.\n\nTo build assets for those flyers I developed a physical-to-digital pipeline: physically spraying paint, scanning the marks, and then tracing and vectorizing them in Illustrator for use as reusable design elements. The team also taught me how to take photographs of their sponsored artists' work and convert them into high-contrast black-and-white bitmap textures for atmospheric backgrounds in ads and flyers.",images:[{src:"/assets/ironlak-internship/MaintainBBQburners.jpg",avif:"/assets/ironlak-internship/MaintainBBQburners.avif",webp:"/assets/ironlak-internship/MaintainBBQburners.webp",alt:"Maintain BBQ Burners flyer",aspectRatio:"16/10",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingBlock:"2.5rem",imagePaddingInline:"2.5rem"}],accentColor:"#1a1a1a"},{id:"bbq-process",layout:"staggered-pair",sectionBackground:"#ffffff",heading:"Physical to Digital",body:"Spray paint marks were scanned and vectorized into reusable assets. Photographs of sponsored artists' work were processed into high-contrast bitmap textures, giving each flyer its atmospheric, in-the-room quality.",images:[{src:"/assets/ironlak-internship/GrassPaintbrush.png",avif:"/assets/ironlak-internship/GrassPaintbrush.avif",webp:"/assets/ironlak-internship/GrassPaintbrush.webp",alt:"Scanned spray paint marks vectorized into a reusable Illustrator brush",aspectRatio:"16/10",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingBlock:"2rem"},{src:"/assets/ironlak-internship/POSE_GENT_1_36X48_2015-B+W.jpg",avif:"/assets/ironlak-internship/POSE_GENT_1_36X48_2015-B+W.avif",webp:"/assets/ironlak-internship/POSE_GENT_1_36X48_2015-B+W.webp",alt:"High-contrast black-and-white bitmap texture of a sponsored artist's mural",aspectRatio:"16/10",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingBlock:"2rem"}]},{id:"bbq-flyers",layout:"image-carousel",sectionBackground:"#f5f5f5",heading:"BBQ Burner Flyers",images:[{src:"/assets/ironlak-internship/Maintainsquare.png",avif:"/assets/ironlak-internship/Maintainsquare.avif",webp:"/assets/ironlak-internship/Maintainsquare.webp",alt:"Maintain square social asset",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/OddsEvensPortrait.jpg",avif:"/assets/ironlak-internship/OddsEvensPortrait.avif",webp:"/assets/ironlak-internship/OddsEvensPortrait.webp",alt:"Odds and Evens BBQ Burners portrait flyer",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"},{src:"/assets/ironlak-internship/MomentumArt1.jpg",avif:"/assets/ironlak-internship/MomentumArt1.avif",webp:"/assets/ironlak-internship/MomentumArt1.webp",alt:"Momentum Art Tech BBQ Burners flyer",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"5rem",imagePaddingBlock:"3rem"}]},{id:"published-work",layout:"text-only",heading:"Published Work",body:"The work reached real audiences. BBQ Burner flyers went live for three shops — Momentum Art Tech, Odds and Evens, and Maintain. An advertisement designed for 14th Street Supply was published in RELISH magazine in San Francisco. Mural festival proposals were also developed for 42 University in collaboration with The Mural Co."},{id:"published-work-image",layout:"full-width-image",images:[{src:"/assets/ironlak-internship/20160922_FreeFinelinerPack.jpg",avif:"/assets/ironlak-internship/20160922_FreeFinelinerPack.avif",webp:"/assets/ironlak-internship/20160922_FreeFinelinerPack.webp",alt:"Free Fineliner Pack promotional flyer",aspectRatio:"16/9",objectFit:"contain",backgroundColor:"#ffffff",imagePaddingInline:"6rem",imagePaddingBlock:"4rem"}]},{id:"tools",layout:"text-only",sectionBackground:"#ffffff",sectionPadding:"1rem 0 3.75rem",heading:"Tools",body:"The primary toolkit across the internship was Adobe Illustrator for asset creation and flyer work, Photoshop for texture and bitmap manipulation, and InDesign for print layout."}]}])}}});
